mapper.select:
SELECT fa.id as id, fa.file_id as fileId, fa.ref_type as refType, fa.ref_id as refId, fa.attached_at as attachedAt, fa.is_deleted as isDeleted, f.name as storedFileName, f.org_name as originalFileName, f.path as s3Key, -- 파일 크기 (실제 컬럼에서 가져오기) COALESCE(f.file_size, '0') as fileSize, -- 확장자 추출 (개선된 방식) CASE WHEN f.org_name IS NOT NULL AND LOCATE('.', f.org_name) > 0 THEN LOWER(SUBSTRING(f.org_name, LOCATE('.', f.org_name) + 1)) ELSE '' END as fileExtension, -- S3 버킷 '' as s3Bucket, f.created_at as createdAt FROM file_attachments fa INNER JOIN file f ON fa.file_id = f.id WHERE 1=1
AND fa.ref_type = #{refType}
AND fa.ref_id = #{refId}
AND fa.is_deleted = #{isDeleted}
ORDER BY fa.attached_at DESC

mapper.update:
UPDATE file_attachments
SET 
    ref_type = #{newRefType},
    ref_id = #{newRefId}
WHERE ref_type = #{oldRefType}
AND ref_id = #{oldRefId}
AND is_deleted = 0
